  "biomeNameSources": [
    {
      "title": "Братья Гримм",
      "url": "https://www.gutenberg.org/files/5314/5314-h/5314-h.htm",
      "theme": "Конкретные сказочные предметы и превращения: можжевельник, поющая кость, саван, печь, зеркало, вороны. Названия — наши предложения по мотивам сказок."
    },
    {
      "title": "Данте · «Божественная комедия»",
      "url": "https://www.gutenberg.org/files/1001/1001-h/1001-h.htm",
      "theme": "Предлагаем использовать путь с проводником, пороги и нисхождение; ледяной нижний мир — отдельный образ для обсуждения. Это художественное произведение, не пересказ исламского учения."
    },
    {
      "title": "Коран · бережная работа с мотивами",
      "url": "https://quran.com/7/46",
      "theme": "Осторожное вдохновение мотивами границы, ожидания и милости (7:46; 39:53). Имена Бога, названия сур, аяты и священные места не превращаем в названия монстров, заклинаний или проклятых локаций. Арабская каллиграфия не назначается декором. Это правило нашей адаптации, не утверждение о реакции всех верующих."
    },
    {
      "title": "«Царство небесное» · Ridley Scott",
      "url": "https://castillayleonfilm.com/en/filmografia/kingdom-of-heaven/",
      "theme": "Фильм добавлен автором в референсы. Предлагаем обсудить осаждённый город, паломничество, долг защитника и напряжение между верой и властью. Конкретные сцены и элементы дизайна ещё выбираются."
    }
  ],
